/** Addresses one `MetadataFix` inside a pending fix's proposals. `MetadataFix` has no server id — it is a detected issue, regenerated per import, not a stored entity — so it is addressed by this field+kind+from triple instead: several `subjects-split` fixes on one book can share a field and kind, differing only in which compound subject they split, so `from` is what disambiguates them. */
export type MetadataFixKeyInput = {
  /** The `MetadataFix.field` of the proposal this key addresses. */
  field: string;
  /** The `MetadataFix.from` of the proposal this key addresses. Included because several `subjects-split` fixes on one book can share both `field` and `kind`, differing only in which compound subject they split — `field`+`kind` alone would be ambiguous between them. */
  from: string;
  /** The `MetadataFix.kind` of the proposal this key addresses. */
  kind: string;
};

export type PendingFixResolution =
  | 'ACCEPT'
  | 'CLEAR'
  | 'DISMISS'
  | 'UNDO';

